// Some portions generated by Codex
package org.eclipse.rdf4j.sail.lmdb;

import static org.assertj.core.api.Assertions.assertThat;
import static org.eclipse.rdf4j.sail.lmdb.LmdbPersistentAdjacencyCompactionAllocationTest.ORIGINAL_SHAPE;
import static org.eclipse.rdf4j.sail.lmdb.LmdbPersistentAdjacencyCompactionAllocationTest.measure;
import static org.eclipse.rdf4j.sail.lmdb.LmdbPersistentAdjacencyCompactionAllocationTest.runChild;

import java.nio.file.Files;
import java.nio.file.Path;

import org.eclipse.rdf4j.sail.lmdb.LmdbPersistentAdjacencyCompactionAllocationTest.Measurement;
import org.eclipse.rdf4j.sail.lmdb.LmdbPersistentAdjacencyCompactionAllocationTest.Shape;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.Timeout;
import org.junit.jupiter.api.io.CleanupMode;
import org.junit.jupiter.api.io.TempDir;

/** Identical page payloads should not require new merge arrays for every predicate/direction partition. */
class LmdbPersistentAdjacencyCompactionPartitionAllocationTest {

	private static final long MAX_EXTRA_PARTITION_ALLOCATION = 64L * 1024;

	@TempDir(cleanup = CleanupMode.ON_SUCCESS)
	Path directory;

	@Test
	@Timeout(90)
	void identicalPagesReuseMergeScratchAcrossPredicatePartitions() throws Exception {
		runChild(directory, LmdbPersistentAdjacencyCompactionPartitionAllocationTest.class,
				"COMPACTION_PARTITION_EXTRA_BYTES=", "COMPACTION_PARTITION_ALLOCATION_COMPLETE");
	}

	public static void main(String[] arguments) throws Exception {
		assertThat(arguments).hasSize(1);
		Path directory = Path.of(arguments[0]);
		Shape onePredicate = new Shape(1, ORIGINAL_SHAPE.predicates() * ORIGINAL_SHAPE.rowsPerPredicate());
		assertThat(onePredicate.rowsPerPredicate()).isEqualTo(16_384);
		assertThat(onePredicate.pageCount()).isEqualTo(32).isEqualTo(ORIGINAL_SHAPE.pageCount());
		assertThat(2 * (ORIGINAL_SHAPE.predicates() - onePredicate.predicates())).isEqualTo(14);

		// Each measurement performs four real warmups, then checks the model, old snapshot, and reopened store.
		Measurement narrow = measure(Files.createDirectory(directory.resolve("one-predicate")), onePredicate);
		Measurement wide = measure(Files.createDirectory(directory.resolve("eight-predicates")), ORIGINAL_SHAPE);
		assertThat(narrow.beforePages()).hasSize(32);
		assertThat(narrow.afterPages()).hasSize(32);
		assertThat(wide.beforePages()).hasSize(32);
		assertThat(wide.afterPages()).hasSize(32);
		for (int page = 0; page < 32; page++) {
			// Predicate IDs belong to the physical fence, not to the serialized CSF value. Global row/neighbor
			// ordinals and the sixteen middle-row tombstones are identical between these two shapes.
			assertThat(wide.beforePages().get(page)).as("identical original serialized page %s", page)
					.containsExactly(narrow.beforePages().get(page));
			assertThat(wide.afterPages().get(page)).as("identical rewritten serialized page %s", page)
					.containsExactly(narrow.afterPages().get(page));
		}
		long extra = wide.allocatedBytes() - narrow.allocatedBytes();
		System.out.println("COMPACTION_PARTITION_ONE_PREDICATE_BYTES=" + narrow.allocatedBytes());
		System.out.println("COMPACTION_PARTITION_EIGHT_PREDICATES_BYTES=" + wide.allocatedBytes());
		System.out.println("COMPACTION_PARTITION_EXTRA_BYTES=" + extra);
		assertThat(narrow.allocatedBytes()).isPositive();
		assertThat(wide.allocatedBytes()).isPositive();
		assertThat(extra).as("fourteen extra partitions may allocate directory/cursor bookkeeping, "
				+ "but not fourteen additional sets of three 2048-long merge arrays")
				.isLessThanOrEqualTo(MAX_EXTRA_PARTITION_ALLOCATION);
		System.out.println("COMPACTION_PARTITION_ALLOCATION_COMPLETE");
	}
}
